export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open (or reuse) an isolated client identified by client_id.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier.' }
        },
        required: ['client_id']
      }
    },
    {
      name: 'client_put',
      description: 'Store a key/value pair in the given client isolated map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier.' },
          key: { type: 'string', description: 'Non-empty key.' },
          value: { type: 'string', description: 'Non-empty value.' }
        },
        required: ['client_id', 'key', 'value']
      }
    },
    {
      name: 'client_get',
      description: 'Read a value for a key from the given client isolated map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier.' },
          key: { type: 'string', description: 'Non-empty key.' }
        },
        required: ['client_id', 'key']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      const { client_id } = args;
      if (!isNonEmptyString(client_id)) {
        throw invalidParams('client_id must be a non-empty string');
      }
      if (!clients.has(client_id)) {
        clients.set(client_id, new Map());
      }
      return { ok: true, client_id };
    }
    case 'client_put': {
      const { client_id, key, value } = args;
      if (!isNonEmptyString(client_id)) {
        throw invalidParams('client_id must be a non-empty string');
      }
      if (!isNonEmptyString(key)) {
        throw invalidParams('key must be a non-empty string');
      }
      if (!isNonEmptyString(value)) {
        throw invalidParams('value must be a non-empty string');
      }
      const map = clients.get(client_id);
      if (!map) {
        throw invalidParams(`unknown client: ${client_id}`);
      }
      map.set(key, value);
      return { ok: true, client_id, key };
    }
    case 'client_get': {
      const { client_id, key } = args;
      if (!isNonEmptyString(client_id)) {
        throw invalidParams('client_id must be a non-empty string');
      }
      if (!isNonEmptyString(key)) {
        throw invalidParams('key must be a non-empty string');
      }
      const map = clients.get(client_id);
      if (!map) {
        throw invalidParams(`unknown client: ${client_id}`);
      }
      if (!map.has(key)) {
        throw invalidParams(`unknown key for client ${client_id}: ${key}`);
      }
      return { client_id, key, value: map.get(key) };
    }
    default:
      throw methodNotFound(`unknown tool: ${name}`);
  }
}
"}

