import {callTool, listTools} from './server.mjs';
const assert = (cond, msg) => { if(!cond) throw new Error('FAIL: '+msg) };

// listTools exposes exactly the 3 tools
const tools = await listTools();
assert(tools.length === 3, 'expected 3 tools, got ' + tools.length);
assert(tools.map(t=>t.name).sort().join(',') === 'client_get,client_put,open_client', 'tool names');

// open + put + get round trip
await callTool('open_client',{client_id:'a'});
await callTool('client_put',{client_id:'a',key:'k',value:'v'});
assert((await callTool('client_get',{client_id:'a',key:'k'})).value === 'v', 'roundtrip');

// isolation: client b cannot see a's key
try { await callTool('client_get',{client_id:'b',key:'k'}); throw new Error('should reject b'); }
catch(e){ assert(/unknown client/.test(e.message), 'unknown client b: '+e.message); }

// unknown client put
try { await callTool('client_put',{client_id:'z',key:'k',value:'v'}); throw new Error('should reject z'); }
catch(e){ assert(/unknown client/.test(e.message), 'unknown client z put: '+e.message); }

// unknown tool
try { await callTool('bogus',{}); throw new Error('should reject bogus'); }
catch(e){ assert(/unknown tool/.test(e.message), 'unknown tool: '+e.message); }

// non-empty strings
try { await callTool('open_client',{client_id:''}); throw new Error('should reject empty id'); }
catch(e){ assert(/non-empty/.test(e.message), 'empty id: '+e.message); }
try { await callTool('client_put',{client_id:'a',key:'',value:'v'}); throw new Error('should reject empty key'); }
catch(e){ assert(/non-empty/.test(e.message), 'empty key: '+e.message); }
try { await callTool('client_put',{client_id:'a',key:'k',value:''}); throw new Error('should reject empty value'); }
catch(e){ assert(/non-empty/.test(e.message), 'empty value: '+e.message); }

console.log('ALL CHECKS PASSED');
""}

